  const domainSha = sha256(readFileSync(resolve(REPO_ROOT, domainPath), "utf8"));
  const oldCatalogBaseline = POST_0555_FORWARD_V48_DB_CATALOG_BASELINE;
  const newCatalogBaseline = POST_0557_FORWARD_V49_DB_CATALOG_BASELINE;
  const oldSeal = registrySeal(REGISTRY_V48_VERSION,
    frozenInventory(REGISTRY_V48_VERSION), oldCatalogBaseline);
  const newSeal = registrySeal(REGISTRY_V49_VERSION, rows, newCatalogBaseline);
  const entrySets = JSON.parse(readFileSync(FULL_ENTRY_SET_SEALS_PATH, "utf8"));
  const oldEntrySet = entrySets[REGISTRY_V48_VERSION];
